<script setup lang="ts">import {computed,onMounted,ref} from 'vue';import {api,dateTime} from '@/lib/api';import StatusBadge from '@/components/StatusBadge.vue';const data=ref<any>({batches:{},open_findings:{},recent_batches:[]}),loading=ref(true);const openCount=computed(()=>Object.values(data.value.open_findings||{}).reduce((a,b)=>Number(a)+Number(b),0));onMounted(async()=>{data.value=(await api.get('/dashboard')).data;loading.value=false});</script>
<template><div v-if="loading" class="card">Carregando...</div><template v-else><section class="kpis"><article><span>Lotes</span><strong>{{data.batches.total||0}}</strong><small>{{data.batches.processing||0}} em processamento</small></article><article><span>Documentos</span><strong>{{data.documents||0}}</strong><small>XMLs normalizados</small></article><article><span>Itens</span><strong>{{data.items||0}}</strong><small>linhas auditadas</small></article><article class="danger"><span>Críticas abertas</span><strong>{{openCount}}</strong><small>{{data.open_findings.critical||0}} críticas</small></article></section><section class="card"><div class="card-title"><div><h2>Auditorias recentes</h2><p>Processamentos mais recentes e seu estado atual.</p></div><RouterLink class="primary" to="/analises/nova">Nova auditoria</RouterLink></div><table><thead><tr><th>Nome</th><th>Empresa</th><th>Status</th><th>Documentos</th><th>Achados</th><th>Criado em</th></tr></thead><tbody><tr v-for="b in data.recent_batches" :key="b.id" @click="$router.push(`/analises/${b.id}`)" class="clickable"><td>{{b.name}}</td><td>{{b.company?.legal_name}}</td><td><StatusBadge :value="b.status"/></td><td>{{b.document_count}}</td><td>{{b.finding_count}}</td><td>{{dateTime(b.created_at)}}</td></tr></tbody></table></section></template>
